const fmt=(v:unknown)=>v===undefined||v===null||v===''?'—':String(v)
const dateOnly=(v:unknown)=>typeof v==='string'?v.slice(0,10):fmt(v)
const statusLabel=(r:Item)=>Number(r.recommended_quantity)>0?'Positive recommendation':r.status==='BLOCKED'?'Blocked':'Zero-quantity decision'
const reason=(v:unknown)=>Array.isArray(v)?v.map(x=>String(x).replaceAll('_',' ').toLowerCase()).join(' · '):'No coded reason'
function useApi<T>(path:string|null,refresh=0){
 const [state,setState]=useState<{data:T|null;loading:boolean;error:string}>({data:null,loading:!!path,error:''})
 useEffect(()=>{if(!path){setState({data:null,loading:false,error:''});return}const ctrl=new AbortController();let active=true
  setState({data:null,loading:true,error:''})
  request<T>(path,{signal:ctrl.signal}).then(data=>{if(active)setState({data,loading:false,error:''})}).catch(e=>{if(active)setState({data:null,loading:false,error:String(e.message||e)})})
  return()=>{active=false;ctrl.abort()}
 },[path,refresh]);return state
}
function Panel({children,title,eyebrow,aside}:{children:ReactNode;title:string;eyebrow?:string;aside?:ReactNode}){return <section className="yf-panel"><div className="yf-panel-head"><div>{eyebrow&&<span className="yf-kicker">{eyebrow}</span>}<h2>{title}</h2></div>{aside}</div>{children}</section>}
function Empty({title='No matching records',detail='Try another filter or select a completed data run.'}:{title?:string;detail?:string}){return <div className="yf-empty"><Database size={23}/><strong>{title}</strong><span>{detail}</span></div>}
function Ready({state,children,emptyText}:{state:{loading:boolean;error:string;data:unknown};children:ReactNode;emptyText?:string}){return state.loading?<div role="status" className="yf-loading"><Loader2 className="yf-spin" size={17}/> Loading backend data…</div>:state.error?<div className="yf-error" role="alert"><CircleAlert size={18}/><span>{state.error}</span></div>:state.data===null?<Empty title={emptyText||'Data unavailable'}/>:<>{children}</>}
function KPICard({title,value,foot,icon:Icon}:{title:string;value:string|number;foot:string;icon:typeof Store}){return <div className="yf-kpi"><div><span>{title}</span><Icon size={18}/></div><strong>{value}</strong><small>{foot}</small></div>}
function Tag({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={'yf-tag yf-'+tone}>{children}</span>}
const tableKeys=(r:Item,i:number)=>String(r.recommendation_id||r.inventory_id||r.sale_id||r.forecast_id||r.store_id||r.sku_id||r.job_id||r.supplier_sku_id||i)
function DataTable({rows,columns,onRow,empty='No records match the current selection.'}:{rows:Item[];columns:{key:string;label:string;show?:(row:Item)=>ReactNode}[];onRow?:(r:Item)=>void;empty?:string}){if(!rows.length)return <Empty detail={empty}/>;return <div className="yf-table-scroll"><table className="yf-table"><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={tableKeys(r,i)} onClick={onRow?()=>onRow(r):undefined} onKeyDown={onRow?e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onRow(r)}}:undefined} tabIndex={onRow?0:undefined} aria-label={onRow?'Inspect '+tableKeys(r,i):undefined} className={onRow?'clickable':''}>{columns.map(c=><td key={c.key}>{c.show?c.show(r):fmt(r[c.key])}</td>)}</tr>)}</tbody></table></div>}
function Paged({path,columns,onRow,refresh=0,empty}:{path:string;columns:{key:string;label:string;show?:(r:Item)=>ReactNode}[];onRow?:(r:Item)=>void;refresh?:number;empty?:string}){
 const [page,setPage]=useState(0),limit=30
 useEffect(()=>setPage(0),[path]);const full=path+(path.includes('?')?'&':'?')+`limit=${limit}&offset=${page*limit}`
 const result=useApi<Page>(full,refresh)
 return <Ready state={result}><DataTable rows={result.data?.items||[]} columns={columns} onRow={onRow} empty={empty}/>{result.data&&<div className="yf-pager"><span>{fmtNumber(result.data.total)} records · Page {page+1}</span><div><button disabled={page===0} onClick={()=>setPage(page-1)}>Previous</button><button disabled={(page+1)*limit>=result.data.total} onClick={()=>setPage(page+1)}>Next <ArrowRight size={13}/></button></div></div>}</Ready>
}
const columns=(...pairs:[string,string][])=>pairs.map(([key,label])=>({key,label}))
const REC_COLUMNS=[{key:'recommendation_id',label:'Recommendation',show:(r:Item)=><b className="yf-mono">{r.recommendation_id}</b>},{key:'store_id',label:'Store'},{key:'sku_id',label:'SKU'},{key:'decision_date',label:'Decision date',show:(r:Item)=>dateOnly(r.decision_date)},{key:'recommended_quantity',label:'Units',show:(r:Item)=><strong>{fmtNumber(r.recommended_quantity)}</strong>},{key:'supplier_name',label:'Supplier'},{key:'status',label:'Decision',show:(r:Item)=><Tag tone={r.status==='BLOCKED'?'bad':Number(r.recommended_quantity)>0?'good':'neutral'}>{statusLabel(r)}</Tag>},{key:'reason_codes',label:'Reasons',show:(r:Item)=><span className="yf-ellipsis">{reason(r.reason_codes)}</span>}]
