function useNavigate(){const [loc,setLoc]=useState(()=>window.location.pathname);useEffect(()=>{const update=()=>setLoc(window.location.pathname);window.addEventListener('popstate',update);return()=>window.removeEventListener('popstate',update)},[]);const go=useCallback((path:string)=>{window.history.pushState({},'',path);setLoc(window.location.pathname);window.scrollTo(0,0)},[]);return [loc,go] as const}
function SkuPicker({value,onChange}:{value:string;onChange:(sku:string)=>void}){
 const [search,setSearch]=useState(''),[debounced,setDebounced]=useState('')
 useEffect(()=>{const t=window.setTimeout(()=>setDebounced(search.trim()),220);return()=>window.clearTimeout(t)},[search])
 const result=useApi<Page>(route('skus',{q:debounced||undefined,limit:30}))
 const options=result.data?.items||[]
 const hasSelected=options.some(r=>r.sku_id===value)
 return <div className="yf-sku-chooser"><input type="search" aria-label="Search SKUs by ID or category" placeholder="Search ID or category" maxLength={80} value={search} onChange={e=>setSearch(e.target.value)}/><select aria-label="Selected SKU" value={value} onChange={e=>onChange(e.target.value)}><option value="">All SKUs</option>{value&&!hasSelected&&<option value={value}>{value} · selected</option>}{options.map(r=><option key={r.sku_id} value={r.sku_id}>{r.sku_id} · {r.category||'Uncategorized'}</option>)}</select><small>{result.loading?'Searching…':result.error?'SKU lookup unavailable':`${options.length} matching options shown`}</small></div>
}
